#!/usr/bin/env python3
"""The home's names for Tadawul codes come from the page's maps (TADAWUL and TADAWUL_MORE in src/template.html): one list, kept in the page.
This writes android/launcher/src/main/java/sa/urtv/home/MarketNames.java from it; tests/market_names_test.py checks the file is current and that
every code of the page resolves to the same name in MarketData.name().   Run: python3 .github/tools/market_names.py   (--check: only compare)"""
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / "android/launcher/src/main/java/sa/urtv/home/MarketNames.java"


def page_names():
    page = (ROOT / "src/template.html").read_text(encoding="utf-8")
    names = {}
    for obj in ("TADAWUL", "TADAWUL_MORE"):
        body = re.search(r"const " + obj + r" = \{(.*?)\n\};", page, re.S).group(1)
        for code, name in re.findall(r"'(\d{4})':'([^']+)'", body):
            names.setdefault(code, name)
    return names


def source(names):
    rows = "".join(f'        {{"{c}", "{n}"}},\n' for c, n in names.items())
    return ("package sa.urtv.home;\n\n"
            "/** GENERATED by .github/tools/market_names.py from the page's TADAWUL and TADAWUL_MORE (src/template.html): do not edit by hand. Plain Java. */\n"
            "final class MarketNames {\n"
            "    private MarketNames() { }\n\n"
            "    static final String[][] ALL = {\n" + rows + "    };\n\n"
            "    /** the page's short Arabic name of a Tadawul code, or null */\n"
            "    static String get(String code) {\n"
            "        for (String[] t : ALL) if (t[0].equals(code)) return t[1];\n"
            "        return null;\n"
            "    }\n}\n")


if __name__ == "__main__":
    text = source(page_names())
    if "--check" in sys.argv:
        sys.exit(0 if OUT.is_file() and OUT.read_text(encoding="utf-8") == text else 1)
    OUT.write_text(text, encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)} ({len(page_names())} codes)")
